    Configuration hadoopConf = new Configuration();
    try (Writer writer = OrcFile.createWriter(new Path(testFilePath), OrcFile.writerOptions(hadoopConf).setSchema(schema))) {
        VectorizedRowBatch batch = schema.createRowBatch();
        List<int[]> intList = prepareListDataForOrcFileTest();
        List<Map<String, Double>> mapList = prepareMapDataForOrcFileTest();
        for (int i = 0; i < 5; i++) {
            batch.size++;
            setColumn(i, batch.cols[0], new ArrayType(new IntType()), Row.of("string", intList.get(i)), 1);
            setColumn(i, batch.cols[1], new MapType(new CharType(), new DoubleType()), Row.of("String", mapList.get(i)), 1);
        }
