    expectedForMap.add("[{\"key\": \"mary\", \"value\": 100.0}, {\"key\": \"lisa\", \"value\": 95.0}, {\"key\": " + "\"anna\", \"value\": 99.0}]");
    expectedForMap.add("null");
    expectedForMap.add("null");
    expectedForMap.add("[{\"key\": \"mary4\", \"value\": 100.4}, {\"key\": \"lisa4\", \"value\": 95.4}, {\"key\":" + " \"anna4\", \"value\": 99.4}]");
    expectedForMap.add("[{\"key\": \"luna5\", \"value\": 98.5}, {\"key\": \"mary5\", \"value\": 100.5}, " + "{\"key\": \"lili5\", \"value\": 97.5}, {\"key\": \"lisa5\", \"value\": 95.5}, {\"key\": \"anna5\"," + " \"value\": 99.5}]");
