public void testConcatNormal() {
    Assert.assertEquals("a|b|c|d", StringUtils.concatCsv(new String[] { "a", "b", "c", "d" }, '|', null, null));
    Assert.assertEquals("a|\\|b|c|d", StringUtils.concatCsv(new String[] { "a", "|b", "c", "d" }, '|', '\\', null));
    Assert.assertEquals("a|\\\\b|c|d", StringUtils.concatCsv(new String[] { "a", "\\b", "c", "d" }, '|', '\\', null));
    Assert.assertEquals("a|\\\"b|c|d", StringUtils.concatCsv(new String[] { "a", "\"b", "c", "d" }, '|', '\\', '\"'));
