}

@Test
public void testExtractNonBuiltInFieldInfos() {
    FieldInfo[] fieldInfos = { new FieldInfo("f1", StringFormatInfo.INSTANCE), new BuiltInFieldInfo("f2", StringFormatInfo.INSTANCE, BuiltInFieldInfo.BuiltInField.MYSQL_METADATA_DATA), new BuiltInFieldInfo("f3", StringFormatInfo.INSTANCE, BuiltInFieldInfo.BuiltInField.DATA_TIME) };
    FieldInfo[] fieldInfos1 = extractNonBuiltInFieldInfos(fieldInfos, false);
    assertEquals(1, fieldInfos1.length);
    assertFalse(fieldInfos1[0] instanceof BuiltInFieldInfo);
    FieldInfo[] fieldInfos2 = extractNonBuiltInFieldInfos(fieldInfos, true);
    assertEquals(2, fieldInfos2.length);
    assertFalse(fieldInfos2[0] instanceof BuiltInFieldInfo);
    assertTrue(fieldInfos2[1] instanceof BuiltInFieldInfo && ((BuiltInFieldInfo) fieldInfos2[1]).getBuiltInField() == BuiltInFieldInfo.BuiltInField.MYSQL_METADATA_DATA);
}

@Test
public void testIsMigrateAll() {
    FieldInfo[] fieldInfos1 = { new FieldInfo("f1", StringFormatInfo.INSTANCE), new BuiltInFieldInfo("f2", StringFormatInfo.INSTANCE, BuiltInFieldInfo.BuiltInField.MYSQL_METADATA_DATA), new BuiltInFieldInfo("f3", StringFormatInfo.INSTANCE, BuiltInFieldInfo.BuiltInField.DATA_TIME) };
    assertTrue(checkWhetherMigrateAll(fieldInfos1));
    FieldInfo[] fieldInfos2 = { new FieldInfo("f1", StringFormatInfo.INSTANCE), new BuiltInFieldInfo("f3", StringFormatInfo.INSTANCE, BuiltInFieldInfo.BuiltInField.DATA_TIME) };
