    Assert.assertEquals(1, retMap.get("consumer_timeout_cnt").longValue());
    Assert.assertEquals(3, retMap.get("broker_hb_exc_cnt").longValue());
    Assert.assertEquals(2, retMap.get("broker_timeout_cnt").longValue());
